import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"63、【既济】 离下坎上","description":"周易尚氏学 - 63、【既济】 离下坎上","frontmatter":{"title":"63、【既济】 离下坎上","description":"周易尚氏学 - 63、【既济】 离下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/068.md","filePath":"zh/classics/shangshi/068.md"}'),h={name:"zh/classics/shangshi/068.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_63、【既济】-离下坎上" tabindex="-1">63、【既济】 离下坎上 <a class="header-anchor" href="#_63、【既济】-离下坎上" aria-label="Permalink to “63、【既济】 离下坎上”">​</a></h1><p>尔雅释天。济谓之齐。疏霁止也。说文同。归藏作岑昕（上雨）。昕（上雨）即霁字。上坎为雨。下离为日。雨过日出。故曰既济。谦传天道下济。即下止也。诗庸（右邑）风。不能旋济。传济止也。庄子齐物论。厉风济则万窍为虚。注济止也。彖传曰终止。杂卦曰既济定。亦皆训济为止。既者尽也。左传桓三年。日有食之既是也。既济者言六爻尽当位而止其所也。止其所而不迁。则道穷。故彖辞不许其终吉。释文释济为度。太玄释为成。惟彖传曰终止。即明释既义。济义。既者尽也。终也。终止即既济。后儒纷纭不已者。以忽略终止。即说卦义也。六爻皆当位有应。故亨。小利贞小字。俞樾云。衍文。卦辞只回亨利贞。故传特以小者亨也释之。如原有小字。则人人皆知。传不如此释矣。子夏传虞翻皆以亨小断句。似非。毛奇龄云。宜以既济亨句小利贞句。小利贞与小利有攸往同。按毛说于句读适矣。然传曰刚柔正。是兼大小言也。今专以属之小。于六交当位之义不合。然则小字属上下读皆不安。征之彖传。其为衍文无疑。俞氏之说。似为可信。盖易之为道。以阳为主。阴与阳绝不平等。故阴得阳应必吉。阳得阴应则不必吉。且有以为凶者。如大过四爻。中孚初爻皆是。既济二四承乘皆阳。又三阴皆有阳应。故小者亨、彖传专以亨属小。亦谓大者不然。大何以不然。凡阳遇重阴必吉。一阴则否。既济三五皆陷阴中。虽三阳皆得位有应。然所应者阴。固与柔爻异也。此传之所以专以亨属之小也。既济者终止。其在既济之初。上下得所。民物咸宜。故初吉。然易之道以变通为贵。无或休息。止而终于是。则易道穷矣。故终乱。</p><p>彖曰。既济亨。小者亨也。利贞。刚柔正而位当也初吉。柔得中也。终止则乱。其道穷也。</p><p>卦三阴三阳。二为阴始得中。放曰初吉。上六则阴之终。故日终止。则乱。坤为乱也。五刚亦得中。不许其吉者。以陷于阴中。与柔得中异也。</p><p>象曰。水在火上。既济。君子以思患而预防之。</p><p>治乱相循环。当治不可忘乱。坎为患为心。故曰思患。</p><p>初九。曳其轮。濡其尾。无咎。</p><p>初应在四。四坎为曳。为轮。为儒。四居坎下。故曰曳。曰尾。所有象皆在应爻。旧解苦于本爻求。胡能合乎。曳儒当有咎。得正故无咎。</p><h3 id="象曰。曳其轮。义无咎也。" tabindex="-1">象曰。曳其轮。义无咎也。 <a class="header-anchor" href="#象曰。曳其轮。义无咎也。" aria-label="Permalink to “象曰。曳其轮。义无咎也。”">​</a></h3><p>得正有应。当然无咎。</p><p>六二。妇丧其茀。匆逐。七日得。</p><p>左传昭五年。火水妃也。故离为坎妇。茀车蔽也。诗硕人曰。翟茀以朝。疏妇人乘车不露儿。车之前后。障以翟羽。以自隐蔽。谓之茀。按周礼有巾车职。巾所以为蔽。即茀也。坎为隐伏为茀。乃坎在外。故丧其茀。盖离为光明。二承乘皆阳。无所隐蔽。如妇人之丧其茀也。庐兆鳖云。初曳轮。二丧弗。义实相因。其改字作绂作髟（下也）者。皆非也。震为逐。半震故勿逐。七日得者。震为复。数七。言至七日。自然来复。与震二同义也。</p><h3 id="象曰。七日得。以中道也" tabindex="-1">象曰。七日得。以中道也 <a class="header-anchor" href="#象曰。七日得。以中道也" aria-label="Permalink to “象曰。七日得。以中道也”">​</a></h3><p>二得中故得。</p><p>九三。高宗伐鬼方。三年克之。小人勿用。</p><p>易林于既未济。偶用半象。本之易也。三四形震。震为帝为主。故曰高宗。曰伐。坎为三年。为鬼方。高宗殷王武丁。鬼方西美国名。范书西羌传云。殷室中衰。诸侯叛。至高宗伐西戎鬼方。三年乃克。又曰周季历伐西落鬼戎是也。坎为艰为劳。故三年乃克。小人谓上六。复上六云。反君道。比上六云。无首凶。师上六云。小人勿用。是上六反君道。无道。为小人之尤。兹于三交发之者。以三应在上六。故预戒也。</p><h3 id="象曰。三年克之。惫也。" tabindex="-1">象曰。三年克之。惫也。 <a class="header-anchor" href="#象曰。三年克之。惫也。" aria-label="Permalink to “象曰。三年克之。惫也。”">​</a></h3><p>坎为劳。故曰惫。惫疲极也。</p><p>六四。襦有衣袖 终日戒。</p><p>此与解三用象同。襦说文缯采色。按缯说文帛也。三四震象。震为衣。襦有。言有帛衣也。四五巽象。巽为帛。亦为枷。如（左衣）败絮也。襦有衣如（左衣）者。言虽有帛衣。衣败絮以自晦。终日戒备也。离为日。坎为忧。故曰终日戒。盖四居两坎之间。坎为盗。俱有所侵犯。故恶衣以自晦。如（左衣）说文引作奴（下系）。释文云子夏作茹。茹柳奴（下系）音同故通用。又云京作絮。按絮即奴（下系）之形讹字。太玄迎道云。裳有衣襦。裳者礼服。襦者短衣。乃有裳不用而衣襦。释此句至为明晰。又释文儒子夏作襦。薛虞云。古文作襦。按襦儒古通。周礼罗氏注。郑司农云。襦为儒有衣絮之襦。弓人注。郑司农云。如（下巾）读为襦有衣奴（下系）之奴（下系）。是襦儒枷古通用。故各家读不同。</p><h3 id="象曰。终日戒。有所疑也。" tabindex="-1">象曰。终日戒。有所疑也。 <a class="header-anchor" href="#象曰。终日戒。有所疑也。" aria-label="Permalink to “象曰。终日戒。有所疑也。”">​</a></h3><p>坎为疑。</p><p>九五。东邻杀牛。不如西邻之论祭。实受其福。</p><p>离位东。故曰东邻。坎位西。故曰西邻。离为牛。兑为毁折为斧。故曰东邻之杀牛。坎为饮食。故为祭。仑（左示）薄祭也。坎为薄。故曰西邻之抡祭。乾为福。杀牛而祭。当受福矣。然不如抡祭受福者。以坎当五。得中正之时也。此离东坎西之确证。郑氏谓离日出东。故曰东邻。坎月生西。故曰西邻。而不知离即在东。坎即在西。则卦象失传之故也。又汉人往往以纣与文王之事说此爻。非。</p><h3 id="象曰。东邻杀牛。不如西邻之时也。实受其福。吉大来也。" tabindex="-1">象曰。东邻杀牛。不如西邻之时也。实受其福。吉大来也。 <a class="header-anchor" href="#象曰。东邻杀牛。不如西邻之时也。实受其福。吉大来也。" aria-label="Permalink to “象曰。东邻杀牛。不如西邻之时也。实受其福。吉大来也。”">​</a></h3><p>受福故吉。</p><p>上六。濡其首。厉。</p><p>坎为首。阴乘阳故襦其首。与比上六之无首义同。彖所谓终乱者此交。</p><h3 id="象曰。濡其首厉。何可久也。" tabindex="-1">象曰。濡其首厉。何可久也。 <a class="header-anchor" href="#象曰。濡其首厉。何可久也。" aria-label="Permalink to “象曰。濡其首厉。何可久也。”">​</a></h3><p>荀爽曰。居上襦五。处高居盛。必当复危。故何可久。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
